            debug!(
                "{} for {:?} due to negated pattern matching neither {:?} nor {:?}: {:?}",
                debug_label,
                path,
                entry.basename_matcher.glob().regex(),
                entry.absolute_matcher.glob().regex(),
                entry.data
            );
            Some(&entry.data)
        } else {
            None
        }
    })
}

